    /// <summary>Whether the table has that key (the event names, keyed by event).</summary>
    internal static bool Has(string key) => Words.ContainsKey(key);

    internal static string Get(Language language, string key)
    {
        var words = Words[key];
        return language switch { Language.En => words.En, Language.Fr => words.Fr, _ => words.Es };
    }
